print(f"Found {len(chapters)} chapters")
for t, _ in chapters[:3]:
    print(f"  - {t}")
print("  ...")
for t, _ in chapters[-2:]:
    print(f"  - {t}")

esc = x.escape
NL = chr(10)

toc_items = NL.join([f'<li><a href="#ch{i}">{esc(t)}</a></li>' for i, (t, _) in enumerate(chapters)])

parts = []
parts.append('<div class="title-page">')
parts.append('<h1>Moon Base: Homecoming</h1>')
parts.append('<p class="subtitle">The First Martian Nation</p>')
parts.append('<p class="series">No Blue Sky — Book V</p>')
