{"content": "#!/usr/bin/env python3
"""Build Book III review PDF with expanded content."""
import os, re, subprocess
import xml.sax.saxutils as x
esc = x.escape
NL = chr(10)

# Read the expanded manuscript
tg_path = "/home/bob/books/Third_Generation/Third_Generation_Manuscript.md"
new_path = "/home/bob/books/Third_Generation/new_chapters_41_46.md"

with open(tg_path) as f:
    tg_content = f.read()

with open(new_path) as f:
    new_content = f.read()

# Find "The End" in TG and insert new content before it
if "**The End**" in tg_content:
    parts = tg_content.split("**The End**")
    tg_body = parts[0]
else:
    tg_body = tg_content

combined = tg_body + "\n\n" + new_content + "\n\n*— THE END —*"

# Parse chapters
lines = combined.split("\n")
chapters = []
current_ch = None
current_lines = []

for line in lines:
    s = line.strip()
    # Detect chapter headings: "## Chapter N" or "## Epilogue" or "# Title (book title)"
    if s.startswith("## Chapter") or s.startswith("## Epilogue") or s.startswith("## Prologue"):
        if current_ch:
            chapters.append((current_ch, "\n".join(current_lines)))
        current_ch = s[2:].strip()  # Remove ## prefix
        current_lines = []
    elif s.startswith("# ") and not s.startswith("## "):
        # Book title line — skip these for chapter separation
        pass
    elif s.startswith("## About the"):
        if current_ch:
            chapters.append((current_ch, "\n".join(current_lines)))
        current_ch = s[2:].strip()
        current_lines = []
    else:
        if current_ch is not None:
            current_lines.append(line)

if current_ch:
    chapters.append((current_ch, "\n".join(current_lines)))

# Remove the first chapter if it's the book title
if chapters and len(chapters[0][0].split()) < 5 and chapters[0][0].startswith("No Blue Sky"):
    chapters = chapters[1:]

print(f"Book III: {len(chapters)} chapters, {len(combined.split())} words")

# Build TOC html
toc_items = []
for i, (title, _) in enumerate(chapters[:46]):  # Limit to story chapters
    short = title[:65] if len(title) > 65 else title
    toc_items.append(f'<li><a href="#ch{i}">{esc(short)}</a></li>')
toc = NL.join(toc_items)

# Build body
parts = []
parts.append('<div class="title-page">')
parts.append('<h1>No Blue Sky: Rivers Under Mars</h1>')
parts.append('<p class="subtitle">The Third Generation</p>')
parts.append('<p class="series">No Blue Sky Series — Book III</p>')
parts.append('<p class="author">Bob Mills</p>')
parts.append('</div>')

parts.append('<div class="copyright-page">')
parts.append('<p><strong>Copyright © 2026 by Bob Mills</strong></p>')
parts.append('<p>All rights reserved. Review proof — not for distribution.</p>')
parts.append('</div>')

parts.append(f'<div class="toc"><h1>Table of Contents</h1><ol>{toc}</ol></div>')

for i, (title, body) in enumerate(chapters):
    blines = body.strip().split(NL)
    html_lines = [f'<h1>{esc(title)}</h1>']
    for bl in blines:
        s = bl.strip()
        if not s:
            continue
        elif s == "---" or s == "***":
            html_lines.append('<hr/>')
        elif s.startswith("## ") and not s.startswith("## Chapter"):
            html_lines.append(f'<h2>{esc(s[3:])}</h2>')
        elif s.startswith("### "):
            html_lines.append(f'<h3>{esc(s[4:])}</h3>')
        elif s.startswith("*") and s.endswith("*") and len(s) > 3:
            html_lines.append(f'<p class="scene-break">{esc(s.strip("*"))}</p>')
        elif s.startswith(">"):
            html_lines.append(f'<blockquote><p>{esc(s[1:].strip())}</p></blockquote>')
        else:
            html_lines.append(f'<p>{esc(s)}</p>')
    parts.append(f'<div id="ch{i}">{NL.join(html_lines)}</div>')

parts.append('<div class="about-author">')
parts.append('<h1>About the Author</h1>')
parts.append('<p>Bob Mills is the author of the No Blue Sky series, an epic saga of humanity\'s expansion across the solar system. With a background in engineering and a passion for authentic hard science fiction, Mills brings technical precision and deep emotional resonance to stories of survival, sovereignty, and the human spirit in space.</p>')
